INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5230816, 759185, 30861, '<td valign="top">Oh you are going to get HAMMERED by the anti-child-nudity police :-(</td>', 'Oh you are going to get HAMMERED by the anti-child-nudity police :-(', '2009-02-01 07:14:06.000000', NULL, 1),
(5230822, 761033, 99506, '<td valign="top">wow i just love the DOF and the over all feel of this 9<br/>Made this only my since I''ve been on DPC favourite</td>', 'wow i just love the DOF and the over all feel of this 9Made this only my since I''ve been on DPC favourite', '2009-02-01 07:20:25.000000', NULL, 1),
(5230827, 760992, 100393, '<td valign="top">Great clarity and colour - the comms wires to the right emphasise the sharpness and the water foreground left emphasises smoothness and lack of noise.</td>', 'Great clarity and colour - the comms wires to the right emphasise the sharpness and the water foreground left emphasises smoothness and lack of noise.', '2009-02-01 07:26:42.000000', NULL, 1),
(5230829, 761598, 100393, '<td valign="top">Very brave image for DPC - I really like it though.</td>', 'Very brave image for DPC - I really like it though.', '2009-02-01 07:26:54.000000', NULL, 1),
(5230838, 753025, 100393, '<td valign="top">These sorts of big cat portraits are seldom as effective as this one.</td>', 'These sorts of big cat portraits are seldom as effective as this one.', '2009-02-01 07:32:28.000000', NULL, 1),
(5230839, 757049, 100393, '<td valign="top">Such a poignant message and a great photo.</td>', 'Such a poignant message and a great photo.', '2009-02-01 07:33:18.000000', NULL, 1),
(5230841, 760477, 79955, '<td valign="top">Nice composition, Editing could be improved, try to remove the halo. 6</td>', 'Nice composition, Editing could be improved, try to remove the halo. 6', '2009-02-01 07:35:04.000000', NULL, 1),
(5230843, 753355, 100393, '<td valign="top">There is no doubt this is a great image, but it is so nearly sharp that the eye longs to see perfect clarity at the eye and beak. I think you may have thought so too since the area to the left of the bird betrays some haloing which suggests some attempts to reclaim final clarity in software.<br/> <br/>Great colours and composition though - overall, very nice indeed.</td>', 'There is no doubt this is a great image, but it is so nearly sharp that the eye longs to see perfect clarity at the eye and beak. I think you may have thought so too since the area to the left of the bird betrays some haloing which suggests some attempts to reclaim final clarity in software. Great colours and composition though - overall, very nice indeed.', '2009-02-01 07:35:37.000000', NULL, 1),
(5230844, 761534, 100393, '<td valign="top">Great strong image - I love bold images like this (and grainy ones too). I''m sure this would have done really well in the ''Grey'' challenge, I''m not sure of the reception you''ll get in a Free Study though.<br/> <br/>This is the sort of thing that might attract a postluminous mention.</td>', 'Great strong image - I love bold images like this (and grainy ones too). I''m sure this would have done really well in the ''Grey'' challenge, I''m not sure of the reception you''ll get in a Free Study though. This is the sort of thing that might attract a postluminous mention.', '2009-02-01 07:35:42.000000', NULL, 1),
(5230846, 753143, 100393, '<td valign="top">Very nice - and a very brave crop.</td>', 'Very nice - and a very brave crop.', '2009-02-01 07:35:46.000000', NULL, 1),
(5230847, 761495, 100393, '<td valign="top">This captures movement really well and the image has a really soft feeling. I see the dilemma you have about the top of the hill behind, crop it and people will think it is sky - cropping it with my hand now though, I think the image would have been cleaner with it cropped out.</td>', 'This captures movement really well and the image has a really soft feeling. I see the dilemma you have about the top of the hill behind, crop it and people will think it is sky - cropping it with my hand now though, I think the image would have been cleaner with it cropped out.', '2009-02-01 07:36:00.000000', NULL, 1),
(5230848, 760867, 100393, '<td valign="top">Interesting image - but a little small on the screen to do justice to your fine subject.</td>', 'Interesting image - but a little small on the screen to do justice to your fine subject.', '2009-02-01 07:36:08.000000', NULL, 1),
(5230856, 761271, 100393, '<td valign="top">With this image being all about straight lines, I think it needs a stronger solid vertical or horizontal to anchor it - I can see that you have matched it to the black white interface mid-bottom, but the right hand vertical has such a close relationship with the right hand border that the non-parallelism here really stands out. Don''t get me wrong, I really like the image, I just think it looks a bit out of whack as presented.</td>', 'With this image being all about straight lines, I think it needs a stronger solid vertical or horizontal to anchor it - I can see that you have matched it to the black white interface mid-bottom, but the right hand vertical has such a close relationship with the right hand border that the non-parallelism here really stands out. Don''t get me wrong, I really like the image, I just think it looks a bit out of whack as presented.', '2009-02-01 07:42:31.000000', NULL, 1),
(5230857, 761584, 79955, '<td valign="top">brilliantly frozen!!!</td>', 'brilliantly frozen!!!', '2009-02-01 07:43:46.000000', NULL, 1),
(5230858, 761584, 100393, '<td valign="top">For me, the background offers the most interest - not because I don''t appreciate the dragonfly - just that the background looks fantastic.</td>', 'For me, the background offers the most interest - not because I don''t appreciate the dragonfly - just that the background looks fantastic.', '2009-02-01 07:44:02.000000', NULL, 1),
(5230861, 760583, 97313, '<td valign="top">I think it''s too dark on the face.</td>', 'I think it''s too dark on the face.', '2009-02-01 07:44:30.000000', NULL, 1),
(5230863, 758926, 97313, '<td valign="top">I''m not too fond of the blurry part on the left of the face.</td>', 'I''m not too fond of the blurry part on the left of the face.', '2009-02-01 07:45:32.000000', NULL, 1),
(5230868, 761625, 79955, '<td valign="top">Nice , lovely lighting , excellent composition too. 8</td>', 'Nice , lovely lighting , excellent composition too. 8', '2009-02-01 07:51:14.000000', NULL, 1),
(5230873, 761631, 100393, '<td valign="top">An interesting and provocative image but quite limited too - the tight crop, the lack of colour, the ambiguity of certain elements all conspire to ensure we get no more than a highly framed peek into this scene. Was that your intention?</td>', 'An interesting and provocative image but quite limited too - the tight crop, the lack of colour, the ambiguity of certain elements all conspire to ensure we get no more than a highly framed peek into this scene. Was that your intention?', '2009-02-01 07:52:57.000000', NULL, 1),
(5230874, 761557, 79955, '<td valign="top">Very well done , 8</td>', 'Very well done , 8', '2009-02-01 07:53:25.000000', NULL, 1),
(5230875, 761422, 76598, '<td valign="top">Technically a good image (exposure, WB, DOF), but I don''t understand or perhaps appreciate the intent of the image.  Is it intended to convey a social situation (litter) or something about the animals.</td>', 'Technically a good image (exposure, WB, DOF), but I don''t understand or perhaps appreciate the intent of the image.  Is it intended to convey a social situation (litter) or something about the animals.', '2009-02-01 07:53:47.000000', NULL, 1),
(5230877, 760864, 79955, '<td valign="top">cool shot!! wonderful capture, 8</td>', 'cool shot!! wonderful capture, 8', '2009-02-01 07:54:37.000000', NULL, 1),
(5230879, 761321, 76598, '<td valign="top">I think this will probably be an under appreciated image.  On the computer screen it doesn''t really blow you away, but there is a lot of meaning and texture in the image...I like this but I fear it will not score as well as it should.</td>', 'I think this will probably be an under appreciated image.  On the computer screen it doesn''t really blow you away, but there is a lot of meaning and texture in the image...I like this but I fear it will not score as well as it should.', '2009-02-01 07:55:38.000000', NULL, 1),
