(5230975, 761555, 99412, '<td valign="top">If I were still living in Washington state I would be suffering through another one of these winters right now. Florida is so much nicer this time of year.<br/>7<br/>:)</td>', 'If I were still living in Washington state I would be suffering through another one of these winters right now. Florida is so much nicer this time of year.7:)', '2009-02-01 08:26:20.000000', NULL, 1),
(5230976, 760788, 3306, '<td valign="top">A sad but interesting picture. Makes me want to rescue this poor dog. I would like to suggest that you crop the picture in a little to remove some of the non visually interesting information in the top of the picture and just a bit on the right.</td>', 'A sad but interesting picture. Makes me want to rescue this poor dog. I would like to suggest that you crop the picture in a little to remove some of the non visually interesting information in the top of the picture and just a bit on the right.', '2009-02-01 08:27:27.000000', NULL, 1),
