INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5231618, 760875, 103069, '<td valign="top">Excellent shot of the falls.</td>', 'Excellent shot of the falls.', '2009-02-01 11:09:03.000000', NULL, 1),
(5231620, 761495, 102024, '<td valign="top">Nice capture, but I really wish the area at the top of the image where you can see over the hill was cropped off.  It is very distracting to me.</td>', 'Nice capture, but I really wish the area at the top of the image where you can see over the hill was cropped off.  It is very distracting to me.', '2009-02-01 11:09:17.000000', NULL, 1),
(5231624, 761625, 103069, '<td valign="top">Wow, This is a nice photo, the colors, the focus, excellent job.</td>', 'Wow, This is a nice photo, the colors, the focus, excellent job.', '2009-02-01 11:12:09.000000', NULL, 1),
(5231625, 760888, 70000, '<td valign="top">Wow I wish I could see a full size version of this. Beautiful colors and texture.</td>', 'Wow I wish I could see a full size version of this. Beautiful colors and texture.', '2009-02-01 11:12:14.000000', NULL, 1),
(5231626, 753400, 102024, '<td valign="top">Very nice scene, but I wish it was sharper and not just sharpened...</td>', 'Very nice scene, but I wish it was sharper and not just sharpened...', '2009-02-01 11:12:22.000000', NULL, 1),
(5231628, 761438, 100393, '<td valign="top">Was the tilt intentional? Personally I think horizons should be horizontal. Also, the point of light mid left is distracting and is begging to be cloned out.<br/> <br/>No doubt this is a great sky and in that part of the image you have served it well, but for me, the other stuff detracts from that central focus.</td>', 'Was the tilt intentional? Personally I think horizons should be horizontal. Also, the point of light mid left is distracting and is begging to be cloned out. No doubt this is a great sky and in that part of the image you have served it well, but for me, the other stuff detracts from that central focus.', '2009-02-01 11:12:33.000000', NULL, 1),
(5231630, 756777, 102024, '<td valign="top">Seems a tad blurry</td>', 'Seems a tad blurry', '2009-02-01 11:13:27.000000', NULL, 1),
(5231633, 761557, 100393, '<td valign="top">A nice picture of the moon but if you have access to the right lens or telescope mount - what is there left for you to do as a photographer? As a consequence - though technically very sound, this lacks enough interest to live with the best entries in this challenge.</td>', 'A nice picture of the moon but if you have access to the right lens or telescope mount - what is there left for you to do as a photographer? As a consequence - though technically very sound, this lacks enough interest to live with the best entries in this challenge.', '2009-02-01 11:14:08.000000', NULL, 1),
(5231634, 760125, 102024, '<td valign="top">Not really sure that the noise grain adds to this image</td>', 'Not really sure that the noise grain adds to this image', '2009-02-01 11:14:15.000000', NULL, 1),
(5231638, 759517, 102024, '<td valign="top">The Horsehead Nebula is a wonderful sight to behold.  Perhaps a tad more contrast could give this image a little more pop</td>', 'The Horsehead Nebula is a wonderful sight to behold.  Perhaps a tad more contrast could give this image a little more pop', '2009-02-01 11:16:14.000000', NULL, 1),
(5231642, 761609, 102024, '<td valign="top">I like the idea, but the lighting is just too bland.  Perhaps if the ambient light was weaker and the direct light was stronger it could isolate the focus of the image and make it more concise.</td>', 'I like the idea, but the lighting is just too bland.  Perhaps if the ambient light was weaker and the direct light was stronger it could isolate the focus of the image and make it more concise.', '2009-02-01 11:18:18.000000', NULL, 1),
(5231646, 755520, 102024, '<td valign="top">Well composed, but there''s some serious pixelation going on here that really detracts from the image.</td>', 'Well composed, but there''s some serious pixelation going on here that really detracts from the image.', '2009-02-01 11:19:57.000000', NULL, 1),
(5231647, 760700, 102024, '<td valign="top">This is a nice capture, but the framing just seems very bland... like a stock photo for an encyclopedia or the like.</td>', 'This is a nice capture, but the framing just seems very bland... like a stock photo for an encyclopedia or the like.', '2009-02-01 11:21:02.000000', NULL, 1),
(5231651, 758931, 36988, '<td valign="top">One of my top picks for the challenge. Nice work with the placement and in particular the shadow makes this a very cool piece of work..</td>', 'One of my top picks for the challenge. Nice work with the placement and in particular the shadow makes this a very cool piece of work..', '2009-02-01 11:23:34.000000', NULL, 1),
(5231652, 753019, 102024, '<td valign="top">Well composed.  The greens seem over saturated.</td>', 'Well composed.  The greens seem over saturated.', '2009-02-01 11:23:37.000000', NULL, 1),
(5231660, 761210, 102024, '<td valign="top">Well composed.  The blur on the mountains in the background seems... uneven and inconsistent.</td>', 'Well composed.  The blur on the mountains in the background seems... uneven and inconsistent.', '2009-02-01 11:26:24.000000', NULL, 1),
(5231662, 761110, 72670, '<td valign="top">Absolutely Awesome!! Good luck. I hope to see this top ten!</td>', 'Absolutely Awesome!! Good luck. I hope to see this top ten!', '2009-02-01 11:27:16.000000', NULL, 1),
(5231664, 760888, 34192, '<td valign="top">Strange and wonderful.  Your soft tones contrast perfectly with the harsh lines of the reeds - sets of a harmonious juxtaposition.9</td>', 'Strange and wonderful.  Your soft tones contrast perfectly with the harsh lines of the reeds - sets of a harmonious juxtaposition.9', '2009-02-01 11:28:19.000000', NULL, 1),
(5231667, 761417, 34192, '<td valign="top">I love the tones, the noise, and the blur.  It sets up the scene wonderfully and fully conveys an emotion attachment. 9</td>', 'I love the tones, the noise, and the blur.  It sets up the scene wonderfully and fully conveys an emotion attachment. 9', '2009-02-01 11:29:48.000000', NULL, 1),
(5231668, 759185, 36988, '<td valign="top">One of my favorites for the challenge. The edit is subtle and very effective and overall the image invokes a very warm and pleasants response from me, the viewer. I do wonder if it will be received fairly by an element that may consider the nature of the subject disturbing and show their displeasure with a barrage of low, lower, lowest votes... I''ve always had a hard time relating to that mindset and look forward to seeing how this plays out.</td>', 'One of my favorites for the challenge. The edit is subtle and very effective and overall the image invokes a very warm and pleasants response from me, the viewer. I do wonder if it will be received fairly by an element that may consider the nature of the subject disturbing and show their displeasure with a barrage of low, lower, lowest votes... I''ve always had a hard time relating to that mindset and look forward to seeing how this plays out.', '2009-02-01 11:30:54.000000', NULL, 1),
(5231669, 761426, 34192, '<td valign="top">The colors and the lighting work very well to convey a sense of place and time. 8</td>', 'The colors and the lighting work very well to convey a sense of place and time. 8', '2009-02-01 11:31:22.000000', NULL, 1),
(5231673, 760909, 34192, '<td valign="top">I think the depth of field here is beautiful.  The soft focus perfectly enhances the subject and works very well with the soft colors.  Amazing job. 9</td>', 'I think the depth of field here is beautiful.  The soft focus perfectly enhances the subject and works very well with the soft colors.  Amazing job. 9', '2009-02-01 11:32:22.000000', NULL, 1),
(5231675, 760852, 36988, '<td valign="top">A very stirring presentation here with lovely tonal range and overall feel. One of my top picks for the challenge. Nicely done.</td>', 'A very stirring presentation here with lovely tonal range and overall feel. One of my top picks for the challenge. Nicely done.', '2009-02-01 11:32:53.000000', NULL, 1),
(5231678, 761110, 34192, '<td valign="top">Very free spirited.  The inclusion of the birds and the echo of her clothes with the wings and the waves really give this image depth.  The tones work well to convey peace. well done! 9</td>', 'Very free spirited.  The inclusion of the birds and the echo of her clothes with the wings and the waves really give this image depth.  The tones work well to convey peace. well done! 9', '2009-02-01 11:33:45.000000', NULL, 1),
(5231685, 761554, 36988, '<td valign="top">I think this is my choice for the blue ribbon. :)<br/>For me everything is right about this image and I really enjoy looking at this alot. A stunning piece of work!</td>', 'I think this is my choice for the blue ribbon. :)For me everything is right about this image and I really enjoy looking at this alot. A stunning piece of work!', '2009-02-01 11:36:52.000000', NULL, 1),
(5231687, 754910, 36988, '<td valign="top">One of my favs for the challenge. Just a good, fun and provocative piece pf work. Well done!</td>', 'One of my favs for the challenge. Just a good, fun and provocative piece pf work. Well done!', '2009-02-01 11:37:38.000000', NULL, 1),
(5231690, 760710, 36988, '<td valign="top">One of my ribbon picks for it''s beauty, simplicity, excellent crop and outstanding edit. Very, very well done!</td>', 'One of my ribbon picks for it''s beauty, simplicity, excellent crop and outstanding edit. Very, very well done!', '2009-02-01 11:39:15.000000', NULL, 1),
(5231694, 760475, 36988, '<td valign="top">One of my top picks for the challenge. Beautifully executed and the pallet chosen is exceptionally effective. Outstanding work!</td>', 'One of my top picks for the challenge. Beautifully executed and the pallet chosen is exceptionally effective. Outstanding work!', '2009-02-01 11:40:34.000000', NULL, 1),
