(5231740, 758956, 103069, '<td valign="top">I think this is a great unusual capture.</td>', 'I think this is a great unusual capture.', '2009-02-01 11:59:03.000000', NULL, 1),
(5231749, 761633, 103069, '<td valign="top">what nice colors...great nice shot.</td>', 'what nice colors...great nice shot.', '2009-02-01 12:04:16.000000', NULL, 1),
