(5232125, 761492, 99394, '<td valign="top">Nice use of B&amp;W</td>', 'Nice use of B&W', '2009-02-01 13:49:37.000000', NULL, 1),
(5232126, 757947, 81362, '<td valign="top">Technically very good, subtle gradation of lighting, nice catchlights, red hair playing off the pinks of her top, focus on the eyes, and also an expression the evokes all kinds of potential stories.</td>', 'Technically very good, subtle gradation of lighting, nice catchlights, red hair playing off the pinks of her top, focus on the eyes, and also an expression the evokes all kinds of potential stories.', '2009-02-01 13:49:38.000000', NULL, 1),
(5232137, 760969, 81362, '<td valign="top">Professional work here. Could be an ad for a brand of beauty products (probably not needed by this model). Hair makes a nice frame while (thank you) not obscuring her eye. I would consider including a little less of her neck, maybe croppoing at the upper neck fold, to make the shape of that negative space less of a downward pointing triangle (that currently pulls the eye away from those wonderful eyes).</td>', 'Professional work here. Could be an ad for a brand of beauty products (probably not needed by this model). Hair makes a nice frame while (thank you) not obscuring her eye. I would consider including a little less of her neck, maybe croppoing at the upper neck fold, to make the shape of that negative space less of a downward pointing triangle (that currently pulls the eye away from those wonderful eyes).', '2009-02-01 13:54:34.000000', NULL, 1),
(5232142, 760856, 29658, '<td valign="top">Perfect composition</td>', 'Perfect composition', '2009-02-01 13:55:39.000000', NULL, 1),
