(5233854, 761551, 81362, '<td valign="top">Light underneath is an excellent idea, taking this into the realm of science fiction transportation. The foreground begins to lose texture - might enhance the subject to crop away a bit of foreground, maybe enough to also eliminate the yellowish spot near the edge on our right.</td>', 'Light underneath is an excellent idea, taking this into the realm of science fiction transportation. The foreground begins to lose texture - might enhance the subject to crop away a bit of foreground, maybe enough to also eliminate the yellowish spot near the edge on our right.', '2009-02-01 22:48:14.000000', NULL, 1),
(5233856, 754873, 98771, '<td valign="top">This may be the best Eagle portrait I''ve seen. Wow that is sharp, very well done.</td>', 'This may be the best Eagle portrait I''ve seen. Wow that is sharp, very well done.', '2009-02-01 22:48:43.000000', NULL, 1),
