(5234754, 758949, 94876, '<td valign="top">She looks familiar.  Nicely cropped.  Lighting creates an uneven look to her skin.</td>', 'She looks familiar.  Nicely cropped.  Lighting creates an uneven look to her skin.', '2009-02-02 10:23:21.000000', NULL, 1),
(5234756, 761572, 94876, '<td valign="top">I might have cropped tighter to the left.  There''s too much going on to the right.  I understand your focal point is the fountain, but my eyes are drawn off to the right by the background.</td>', 'I might have cropped tighter to the left.  There''s too much going on to the right.  I understand your focal point is the fountain, but my eyes are drawn off to the right by the background.', '2009-02-02 10:24:44.000000', NULL, 1),
(5234759, 761273, 94876, '<td valign="top">This is almost a great photograph.  It lacks sharpness, whether that''s deliberate or not, I''m not sure.  I think it would benefit from a teensy bit lower crop on the top border.  That highlight breaking through is distracting.</td>', 'This is almost a great photograph.  It lacks sharpness, whether that''s deliberate or not, I''m not sure.  I think it would benefit from a teensy bit lower crop on the top border.  That highlight breaking through is distracting.', '2009-02-02 10:26:19.000000', NULL, 1),
