(5240221, 758440, 7343, '<td valign="top">I always like the variety of shots in the monthy ''best of'' series.  Don''t see many like this one.  I like the colors and smoothness of the light.  Very pretty.</td>', 'I always like the variety of shots in the monthy ''best of'' series.  Don''t see many like this one.  I like the colors and smoothness of the light.  Very pretty.', '2009-02-05 01:17:54.000000', NULL, 1),
(5240222, 760375, 7343, '<td valign="top">Points for weirdness!  Funny looking dude.</td>', 'Points for weirdness!  Funny looking dude.', '2009-02-05 01:18:37.000000', NULL, 1),
(5240223, 756653, 7343, '<td valign="top">I like the idea of the shot.  Bird seems cold but contemplative...  I like the composition, depth of field as well.  Not sure there was much you could do about it, but the background is just a bit distracting and the bird doesn''t seem quite in focus (there seems to be a little ''halo'' like thing around him on my monitor anyway).  Nice shot though.</td>', 'I like the idea of the shot.  Bird seems cold but contemplative...  I like the composition, depth of field as well.  Not sure there was much you could do about it, but the background is just a bit distracting and the bird doesn''t seem quite in focus (there seems to be a little ''halo'' like thing around him on my monitor anyway).  Nice shot though.', '2009-02-05 01:20:12.000000', NULL, 1),
(5240225, 761249, 7343, '<td valign="top">Pretty shot.  Like the play between vertical straight bldgs and curvy color bridge.  Sky is neat too.  Nice.</td>', 'Pretty shot.  Like the play between vertical straight bldgs and curvy color bridge.  Sky is neat too.  Nice.', '2009-02-05 01:21:21.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5240226, 753701, 7343, '<td valign="top">Very postcards (in a good way.)  I like that the trees (branches esp.) are more brown than pure black.  Good composition.</td>', 'Very postcards (in a good way.)  I like that the trees (branches esp.) are more brown than pure black.  Good composition.', '2009-02-05 01:22:11.000000', NULL, 1),
(5240228, 753400, 7343, '<td valign="top">Hartbeespoort.  Where is that, South Africa?  Very pretty.  Like the blurred water and greens.  The trees seem a little too dark in parts.  Wish the bottom left was cut out.  Do you have a shot a little more zoomed in?  Nice pic.</td>', 'Hartbeespoort.  Where is that, South Africa?  Very pretty.  Like the blurred water and greens.  The trees seem a little too dark in parts.  Wish the bottom left was cut out.  Do you have a shot a little more zoomed in?  Nice pic.', '2009-02-05 01:24:10.000000', NULL, 1),
(5240229, 761589, 7343, '<td valign="top">Very pretty!  How''d you get this one?  The white vertical thingy on the left is a little distracting.  Nice.</td>', 'Very pretty!  How''d you get this one?  The white vertical thingy on the left is a little distracting.  Nice.', '2009-02-05 01:25:29.000000', NULL, 1),
(5240230, 761667, 7343, '<td valign="top">Nice effect.  I like this shot.</td>', 'Nice effect.  I like this shot.', '2009-02-05 01:26:01.000000', NULL, 1),
(5240316, 761096, 16046, '<td valign="top">Love this, awesome</td>', 'Love this, awesome', '2009-02-05 03:20:38.000000', NULL, 1),
(5240412, 761508, 100393, '<td valign="top">Great image, I''m normally relaxed about borders but I''m sure this one will be hurting your score.</td>', 'Great image, I''m normally relaxed about borders but I''m sure this one will be hurting your score.', '2009-02-05 06:21:38.000000', NULL, 1),
(5240478, 761117, 101492, '<td valign="top">This could have been just as seductive without the full nudity, maybe more so.<br/> <br/>Since you have made such a fuss, via private message, about my initial comment above, I decided to come back and give it another look.  It reminds me of an early Marilyn Monroe type of shot.  There is too much light on her hair and backside in the background, detracting from her face and eyes, which could be absolutely captivating if better highlighted.  Perspective is nice.  I have adjusted my score accordingly.</td>', 'This could have been just as seductive without the full nudity, maybe more so. Since you have made such a fuss, via private message, about my initial comment above, I decided to come back and give it another look.  It reminds me of an early Marilyn Monroe type of shot.  There is too much light on her hair and backside in the background, detracting from her face and eyes, which could be absolutely captivating if better highlighted.  Perspective is nice.  I have adjusted my score accordingly.', '2009-02-05 08:14:26.000000', NULL, 1),
(5240561, 758493, 98171, '<td valign="top">I wish this was in color.</td>', 'I wish this was in color.', '2009-02-05 09:40:20.000000', NULL, 1),
(5240572, 761495, 98171, '<td valign="top">You should have cropped the top of the image. It is distracting. Otherwise, great image =) Pretty horse.</td>', 'You should have cropped the top of the image. It is distracting. Otherwise, great image =) Pretty horse.', '2009-02-05 09:47:50.000000', NULL, 1),
(5240597, 759772, 65234, '<td valign="top">Bold crop and nice pinks.  Your whites are tinged a bit cyan so a white balance correction might be needed, and a sharpening boost to make the petals stand out more.  While shooting, I would try another light low on the left to minimize the petal shadows and add more depth to the flower.  If this was taken outside and another light isn''t an option, I''d play with some different angles to either eliminate the shadows or make them a key part of the composition.</td>', 'Bold crop and nice pinks.  Your whites are tinged a bit cyan so a white balance correction might be needed, and a sharpening boost to make the petals stand out more.  While shooting, I would try another light low on the left to minimize the petal shadows and add more depth to the flower.  If this was taken outside and another light isn''t an option, I''d play with some different angles to either eliminate the shadows or make them a key part of the composition.', '2009-02-05 10:08:09.000000', NULL, 1),
(5240598, 760698, 65234, '<td valign="top">Found one!  Nice pastels and I like how the edge of the sand and the bright clouds make a sort of V pattern framing the water and low clouds.</td>', 'Found one!  Nice pastels and I like how the edge of the sand and the bright clouds make a sort of V pattern framing the water and low clouds.', '2009-02-05 10:09:26.000000', NULL, 1),
(5240604, 761657, 65234, '<td valign="top">That''s amazing!  Great timing to catch those poor fish still struggling  and the water splashing.  I''d dodge a bit of catchlight in the pelican''s eyes so they don''t look so much like black holes, lighten up the midtones a tad and dodge the face a little to bring out more detail.  But I''m in awe of your timing!</td>', 'That''s amazing!  Great timing to catch those poor fish still struggling  and the water splashing.  I''d dodge a bit of catchlight in the pelican''s eyes so they don''t look so much like black holes, lighten up the midtones a tad and dodge the face a little to bring out more detail.  But I''m in awe of your timing!', '2009-02-05 10:13:14.000000', NULL, 1),
(5240608, 760821, 65234, '<td valign="top">Well, that''s unusual.  Sepia is great for this with that wonderful curvy old-fashioned script, and the marble and leaf with the document are an intriguing combination visually.</td>', 'Well, that''s unusual.  Sepia is great for this with that wonderful curvy old-fashioned script, and the marble and leaf with the document are an intriguing combination visually.', '2009-02-05 10:16:37.000000', NULL, 1),
