(5243043, 760969, 88204, '<td valign="top">Wonderful sparkling eyes, great composition. Great shot! 9</td>', 'Wonderful sparkling eyes, great composition. Great shot! 9', '2009-02-06 20:35:37.000000', NULL, 1),
(5243044, 760986, 88204, '<td valign="top">Great lighting. It really makes the faces pop. I''m curious to know your setup. Environment is very cool... kind of medieval. Excellent group shot! 9</td>', 'Great lighting. It really makes the faces pop. I''m curious to know your setup. Environment is very cool... kind of medieval. Excellent group shot! 9', '2009-02-06 20:35:40.000000', NULL, 1),
(5243045, 760710, 88204, '<td valign="top">Beautiful even lighting. Nice composition. With the eyes looking downward it directs my attention to the lips... a good beauty shot.</td>', 'Beautiful even lighting. Nice composition. With the eyes looking downward it directs my attention to the lips... a good beauty shot.', '2009-02-06 20:35:44.000000', NULL, 1),
(5243046, 761591, 88204, '<td valign="top">Great shot. I like the soft side lighting. The lines in the background are nice and simple but interesting. Great casual expression... looks very natural. 8</td>', 'Great shot. I like the soft side lighting. The lines in the background are nice and simple but interesting. Great casual expression... looks very natural. 8', '2009-02-06 20:36:34.000000', NULL, 1),
(5243050, 761541, 88204, '<td valign="top">Adorable! I like the hand of the mother too (except for the bandaid). 8</td>', 'Adorable! I like the hand of the mother too (except for the bandaid). 8', '2009-02-06 20:37:05.000000', NULL, 1),
(5243052, 761531, 88204, '<td valign="top">Great expressions! Nice use of simple colors. Nice soft lighting. 8</td>', 'Great expressions! Nice use of simple colors. Nice soft lighting. 8', '2009-02-06 20:37:43.000000', NULL, 1),
(5243053, 761504, 88204, '<td valign="top">Adorable! Great angle. 8</td>', 'Adorable! Great angle. 8', '2009-02-06 20:37:57.000000', NULL, 1),
(5243054, 761343, 88204, '<td valign="top">Great clarity and sharpness on the eye. Shallow DoF adds intrigue. 8</td>', 'Great clarity and sharpness on the eye. Shallow DoF adds intrigue. 8', '2009-02-06 20:38:09.000000', NULL, 1),
(5243126, 761175, 51747, '<td valign="top">I like the lighting on the fish. He does look ''Grumpy''  The little spots on the glass are real and they''re there. I''m glad you left them.</td>', 'I like the lighting on the fish. He does look ''Grumpy''  The little spots on the glass are real and they''re there. I''m glad you left them.', '2009-02-06 22:17:40.000000', NULL, 1),
(5243129, 761425, 51747, '<td valign="top">I see this in Pennsylvania. It could be almost anywhere in the US.</td>', 'I see this in Pennsylvania. It could be almost anywhere in the US.', '2009-02-06 22:19:42.000000', NULL, 1),
(5243140, 757336, 51747, '<td valign="top">This is a nice version of a familiar subject. Well done.</td>', 'This is a nice version of a familiar subject. Well done.', '2009-02-06 22:23:49.000000', NULL, 1),
(5243141, 756243, 51747, '<td valign="top">I like it! I  would like a little less sky (just MHO).</td>', 'I like it! I  would like a little less sky (just MHO).', '2009-02-06 22:25:02.000000', NULL, 1),
(5243143, 758931, 51747, '<td valign="top">I think the shadow is more interesting than the Lizard! Nice find.</td>', 'I think the shadow is more interesting than the Lizard! Nice find.', '2009-02-06 22:26:13.000000', NULL, 1),
(5243144, 759900, 51747, '<td valign="top">Good crop. I would never have seen this.</td>', 'Good crop. I would never have seen this.', '2009-02-06 22:26:50.000000', NULL, 1),
(5243149, 760534, 51747, '<td valign="top">The tones are great in this photo.Nice details in the bird.</td>', 'The tones are great in this photo.Nice details in the bird.', '2009-02-06 22:29:55.000000', NULL, 1),
(5243152, 758493, 51747, '<td valign="top">A rare B&amp;W Flamingo. It does have a certain something though. Nice job.</td>', 'A rare B&W Flamingo. It does have a certain something though. Nice job.', '2009-02-06 22:31:23.000000', NULL, 1),
